CREATE INDEX CONCURRENTLY IF NOT EXISTS agent_task_wakeup_active_idx ON agent_task_queue USING btree (((context ->> 'wakeup_id'::text)), ((status = ANY (ARRAY['running'::text, 'waiting_local_directory'::text, 'dispatched'::text]))) DESC, created_at DESC, id DESC) WHERE (((context ->> 'wakeup_id'::text) IS NOT NULL) AND (status = ANY (ARRAY['queued'::text, 'deferred'::text, 'dispatched'::text, 'running'::text, 'waiting_local_directory'::text])));
